#[test]
fn pending_permission_survives_remote_connection_loss_in_agent_host() {
    let (mut host, project, storage) = test_host("pending-permission-reconnect");
    let session = host.create_session("Remote").expect("session");
    let version = host.session(&session).expect("session").proposal.version;
    let run = host.start_run_authorized(&session, version, "test").expect("run");
    assert_eq!(
        host.check_permission(&run, AgentCapability::FrameCapture)
            .expect("permission request"),
        crate::agent_host::PermissionCheck::RequiresApproval
    );
    let before = snapshot_json(
        &host,
        "project-a",
        &session,
        host.pending_permission(),
    )
    .expect("snapshot before disconnect");
    drop(MutationCache::default());
    let after = snapshot_json(
        &host,
        "project-a",
        &session,
        host.pending_permission(),
    )
    .expect("snapshot after reconnect");
    assert_eq!(before["pending_permission"]["run_id"], run);
    assert_eq!(after["pending_permission"]["run_id"], run);
    assert_eq!(
        after["pending_permission"]["capability"],
        serde_json::json!("frame_capture")
    );
    let _ = fs::remove_dir_all(project);
    let _ = fs::remove_dir_all(storage);
}

